(function () {
  'use strict';

  // ── Mouse ───────────────────────────────────────────────
  var mouse = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
  document.addEventListener('mousemove', function (e) {
    mouse.x = e.clientX;
    mouse.y = e.clientY;
  });

  // ── Helpers ─────────────────────────────────────────────
  function rand(a, b) { return a + Math.random() * (b - a); }
  function lerp(a, b, t) { return a + (b - a) * t; }
  function rgba(r, g, b, a) {
    return 'rgba(' + Math.round(r) + ',' + Math.round(g) + ',' + Math.round(b) + ',' + a + ')';
  }

  // ── Aspect → colour map ─────────────────────────────────
  var ASPECT_COLORS = {
    'air':          [190, 220, 255],
    'earth':        [130,  95,  45],
    'fire':         [255, 110,  20],
    'water':        [ 50, 130, 255],
    'order':        [210, 215, 255],
    'entropy':      [ 90,  20, 150],
    'void':         [ 55,  10, 100],
    'light':        [255, 245, 130],
    'energy':       [255, 200,  50],
    'motion':       [ 60, 200, 160],
    'stone':        [160, 150, 140],
    'life':         [ 80, 200,  70],
    'cold':         [160, 215, 255],
    'crystal':      [190, 235, 255],
    'death':        [ 60, 130,  60],
    'flight':       [130, 195, 255],
    'darkness':     [ 35,  10,  65],
    'soul':         [190, 200, 255],
    'heal':         [110, 225, 130],
    'travel':       [195, 150,  75],
    'poison':       [110, 200,  50],
    'eldritch':     [155,  50, 205],
    'magic':        [165,  80, 225],
    'aura':         [210, 155, 255],
    'taint':        [125,  55, 165],
    'seed':         [185, 215,  80],
    'slime':        [ 85, 205,  85],
    'plant':        [ 65, 165,  65],
    'tree':         [100,  65,  25],
    'beast':        [205, 145,  65],
    'flesh':        [225, 105, 105],
    'undead':       [ 85, 125,  80],
    'mind':         [105, 145, 255],
    'senses':       [145, 185, 255],
    'man':          [205, 165, 105],
    'crop':         [225, 205,  85],
    'harvest':      [240, 185,  65],
    'metal':        [185, 185, 200],
    'mine':         [145, 125, 105],
    'tool':         [185, 145,  80],
    'weapon':       [205,  80,  80],
    'armor':        [105, 145, 205],
    'hunger':       [185,  50,  50],
    'greed':        [225, 195,  50],
    'trap':         [145,  60, 185],
    'mechanism':    [185, 135,  60],
    'cloth':        [205, 215, 245],
    'craft':        [165, 125,  65],
    'exchange':     [215, 175,  60],
    'weather':      [145, 155, 185],
    'wrath':        [225,  55,  55],
    'nether':       [185,  65,  25],
    'gluttony':     [135,  65, 145],
    'envy':         [ 65, 165,  85],
    'sloth':        [125, 125, 145],
    'pride':        [225, 185,  55],
    'lust':         [225,  85, 125],
    'time':         [185, 205, 255],
    'electricity':  [255, 235,  55],
    'magnetism':    [125, 135, 205],
    'cheatiness':   [255, 165,  55],
    'radioactivity':[165, 230, 100],
    'stupidity':    [145,  90,  55],
  };

  // ── Sprite sheet constants (wisp.png = 4×4 grid, 256×256) ──
  var SPRITE_COLS   = 4;
  var SPRITE_ROWS   = 4;
  var SPRITE_FRAMES = SPRITE_COLS * SPRITE_ROWS; // 16
  var SPRITE_URL    = 'data:image/png;base64,';
  var FRAMES_PER_TICK = 4; // render frames between sprite frame advances (~15fps sprite)

  // ── Wisp configs ────────────────────────────────────────
  var CONFIGS = [
    {
      r: 190, g: 85, b: 255,        // Auram — violet
      size: 96, speed: 0.038,
      wobble: { ax: 44, ay: 30, fx: 0.65, fy: 0.48 },
      showAfter: 2800,
      lifetime: [14000, 24000],
      hidetime:  [5000,  13000],
    },
    {
      r: 95, g: 215, b: 255,         // Aqua — icy cyan
      size: 72, speed: 0.027,
      wobble: { ax: 60, ay: 42, fx: 0.40, fy: 0.62 },
      showAfter: 9500,
      lifetime: [10000, 18000],
      hidetime:  [7000,  15000],
    }
  ];

  // ── Wisp ────────────────────────────────────────────────
  function Wisp(cfg, t0) {
    this.cfg     = cfg;
    this.t0      = t0;
    this.x       = rand(150, window.innerWidth  - 150);
    this.y       = rand(150, window.innerHeight - 150);
    this.phi     = Math.random() * Math.PI * 2;
    this.visible = false;
    this.frameN  = 0;
    this.spriteFrame = Math.floor(Math.random() * SPRITE_FRAMES);

    this.r  = cfg.r;  this.g  = cfg.g;  this.b  = cfg.b;
    this.tr = cfg.r;  this.tg = cfg.g;  this.tb = cfg.b;
    this.dr = cfg.r;  this.dg = cfg.g;  this.db = cfg.b;

    this.el = this._build();
    this._applyColor();

    var self = this;
    setTimeout(function () { self.show(); }, cfg.showAfter + rand(0, 2000));
  }

  Wisp.prototype._build = function () {
    var el = document.createElement('div');
    el.className = 'wisp';
    var s    = this.cfg.size;
    var pct  = (SPRITE_COLS * 100) + '%'; // 400%

    el.style.cssText =
      'position:fixed;top:0;left:0;pointer-events:none;z-index:9999;' +
      'width:' + s + 'px;height:' + s + 'px;border-radius:50%;' +
      'will-change:transform;opacity:0;transition:opacity 2.5s ease;' +
      '-webkit-mask-image:url(' + SPRITE_URL + ');' +
      'mask-image:url(' + SPRITE_URL + ');' +
      '-webkit-mask-size:' + pct + ' ' + pct + ';' +
      'mask-size:' + pct + ' ' + pct + ';' +
      '-webkit-mask-position:0% 0%;' +
      'mask-position:0% 0%;';
    document.body.appendChild(el);
    return el;
  };

  Wisp.prototype._applyColor = function () {
    var r = this.r, g = this.g, b = this.b, s = this.cfg.size;
    // Ring-shaped gradient — bright at the wisp band, matching the sprite silhouette
    this.el.style.background =
      'radial-gradient(circle,' +
      'rgba(255,255,255,0.55) 0%,' +
      rgba(r, g, b, 0.50) + ' 22%,' +
      rgba(r, g, b, 1.00) + ' 42%,' +
      rgba(r, g, b, 0.70) + ' 58%,' +
      'transparent 75%)';
    this.el.style.boxShadow =
      '0 0 ' + (s * 0.55) + 'px ' + (s * 0.28) + 'px ' + rgba(r, g, b, 0.80) + ',' +
      '0 0 ' + (s * 1.20) + 'px ' + (s * 0.60) + 'px ' + rgba(r, g, b, 0.38) + ',' +
      '0 0 ' + (s * 2.80) + 'px ' + (s * 1.10) + 'px ' + rgba(r, g, b, 0.15);
  };

  Wisp.prototype._applyMaskFrame = function () {
    var col  = this.spriteFrame % SPRITE_COLS;
    var row  = Math.floor(this.spriteFrame / SPRITE_COLS);
    var pctX = col  * (100 / (SPRITE_COLS - 1));  // 0, 33.33, 66.67, 100
    var pctY = row  * (100 / (SPRITE_ROWS - 1));
    var pos  = pctX + '% ' + pctY + '%';
    this.el.style.webkitMaskPosition = pos;
    this.el.style.maskPosition       = pos;
  };

  Wisp.prototype.setColor = function (r, g, b) {
    this.tr = r; this.tg = g; this.tb = b;
  };

  Wisp.prototype.resetColor = function () {
    this.tr = this.dr; this.tg = this.dg; this.tb = this.db;
  };

  Wisp.prototype.show = function () {
    this.visible = true;
    this.el.style.opacity = '1';
    var self = this;
    setTimeout(function () { self.hide(); },
      rand(this.cfg.lifetime[0], this.cfg.lifetime[1]));
  };

  Wisp.prototype.hide = function () {
    this.visible = false;
    this.el.style.opacity = '0';
    var self = this;
    setTimeout(function () { self.show(); },
      rand(this.cfg.hidetime[0], this.cfg.hidetime[1]));
  };

  Wisp.prototype.particle = function () {
    var r = this.r, g = this.g, b = this.b;
    var s = this.cfg.size;
    var el = document.createElement('div');
    var ps = rand(2, 6);
    el.style.cssText =
      'position:fixed;top:0;left:0;pointer-events:none;z-index:9998;' +
      'width:' + ps + 'px;height:' + ps + 'px;border-radius:50%;' +
      'background:' + rgba(r, g, b, 0.9) + ';' +
      'box-shadow:0 0 ' + (ps * 2) + 'px ' + rgba(r, g, b, 0.65) + ';' +
      'will-change:transform,opacity;';
    document.body.appendChild(el);

    var px  = this.x + s * 0.5;
    var py  = this.y + s * 0.5;
    var ang = Math.random() * Math.PI * 2;
    var spd = rand(0.4, 1.2);
    var vx  = Math.cos(ang) * spd;
    var vy  = Math.sin(ang) * spd - rand(0.3, 0.8);
    var life = rand(0.55, 1.0);
    var dec  = rand(0.016, 0.026);

    el.style.transform = 'translate(' + px + 'px,' + py + 'px)';

    (function tick() {
      life -= dec;
      if (life <= 0) { el.remove(); return; }
      px += vx; py += vy; vy -= 0.016;
      el.style.transform = 'translate(' + px + 'px,' + py + 'px) scale(' + life + ')';
      el.style.opacity   = Math.min(life, 0.72);
      requestAnimationFrame(tick);
    }());
  };

  Wisp.prototype.update = function (now) {
    var t = (now - this.t0) / 1000;
    var w = this.cfg.wobble;
    var s = this.cfg.size;

    // Smooth colour lerp
    var dr = this.tr - this.r, dg = this.tg - this.g, db = this.tb - this.b;
    if (Math.abs(dr) > 0.5 || Math.abs(dg) > 0.5 || Math.abs(db) > 0.5) {
      this.r = lerp(this.r, this.tr, 0.045);
      this.g = lerp(this.g, this.tg, 0.045);
      this.b = lerp(this.b, this.tb, 0.045);
      this._applyColor();
    }

    // Advance sprite frame
    if (this.frameN % FRAMES_PER_TICK === 0) {
      this.spriteFrame = (this.spriteFrame + 1) % SPRITE_FRAMES;
      this._applyMaskFrame();
    }

    // Wobble + lazy follow
    var wx = Math.sin(t * w.fx + this.phi)       * w.ax;
    var wy = Math.cos(t * w.fy + this.phi + 1.3) * w.ay;
    var tx = mouse.x + wx - s * 0.5;
    var ty = mouse.y + wy - s * 0.5;

    this.x += (tx - this.x) * this.cfg.speed;
    this.y += (ty - this.y) * this.cfg.speed;
    this.el.style.transform = 'translate(' + this.x + 'px,' + this.y + 'px)';

    if (this.visible && ++this.frameN % 5 === 0) {
      this.particle();
    }
  };

  // ── Init ────────────────────────────────────────────────
  var t0    = performance.now();
  var wisps = CONFIGS.map(function (cfg) { return new Wisp(cfg, t0); });

  // Aspect hover → wisp colour
  var lastAspectId = null;
  document.addEventListener('mouseover', function (e) {
    var el = e.target;
    while (el && el.tagName !== 'BODY') {
      if (el.classList && el.classList.contains('aspect') && el.id) {
        if (el.id !== lastAspectId) {
          lastAspectId = el.id;
          var col = ASPECT_COLORS[el.id];
          if (col) wisps.forEach(function (w) { w.setColor(col[0], col[1], col[2]); });
        }
        return;
      }
      el = el.parentElement;
    }
    if (lastAspectId !== null) {
      lastAspectId = null;
      wisps.forEach(function (w) { w.resetColor(); });
    }
  });

  // Arcane circle on Find Connection
  window.addEventListener('load', function () {
    var btn = document.getElementById('find_connection');
    var ac  = document.getElementById('arcane-circle');
    if (!btn || !ac) return;
    btn.addEventListener('click', function () {
      ac.classList.remove('is-casting');
      void ac.offsetWidth;
      ac.classList.add('is-casting');
      setTimeout(function () { ac.classList.remove('is-casting'); }, 2400);
    });
  });

  // Render loop
  (function loop(now) {
    wisps.forEach(function (w) { w.update(now); });
    requestAnimationFrame(loop);
  }(t0));

}());
